\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{microtype}
\pagestyle{empty}

% ── World Bank Institutional Palette ──
\definecolor{primary}{HTML}{003366}    % deep navy
\definecolor{secondary}{HTML}{0058A3}  % WB blue
\definecolor{accent}{HTML}{E8A020}     % amber/gold
\definecolor{teal}{HTML}{007B7F}       % teal accent
\definecolor{bgposter}{HTML}{F4F6F9}   % light blue-grey background
\definecolor{redbg}{HTML}{EFF4FA}      % blue-tinted card bg
\definecolor{bluebg}{HTML}{EAF5F5}     % teal-tinted card bg
\definecolor{darkbg}{HTML}{F0F4EE}     % neutral card bg
\definecolor{amberbg}{HTML}{FDF6E3}    % amber-tinted card bg
\definecolor{redtitlebg}{HTML}{DAEAF8}
\definecolor{bluetitlebg}{HTML}{D4ECEC}
\definecolor{darktitlebg}{HTML}{D6E8F0}
\definecolor{ambertitlebg}{HTML}{FAEDCA}
\definecolor{textdark}{HTML}{111827}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{FEF3C7}
\definecolor{statborder}{HTML}{D97706}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=5pt, parsep=1pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=22pt, itemsep=5pt, parsep=1pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Card styles ──
\tcbset{
  navycard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=redtitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={primary!40},
    valign=top, drop shadow={opacity=0.16},
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{teal},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{teal},
    coltitle=teal, colbacktitle=bluetitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={teal!40},
    valign=top, drop shadow={opacity=0.16},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=darktitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={secondary!40},
    valign=top, drop shadow={opacity=0.16},
  },
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=amberbg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{accent!80!black},
    coltitle=accent!80!black, colbacktitle=ambertitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.16},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!15!white,
    borderline west={6pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=5pt, bottomtitle=5pt,
    valign=top, drop shadow={opacity=0.20},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ══════════════════════════════════════════════
% TITLE BAR (rows 1–4)
% ══════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary,
  arc=0pt, boxrule=0pt,
  left=32pt, right=32pt, top=14pt, bottom=10pt,
  halign=center, valign=center,
  drop shadow={opacity=0.28}
]{name=title, column=1, span=2, between=top and row4}{%
  {\fontsize{64}{76}\selectfont\bfseries\color{white}%
    Global Economic Prospects}\\[8pt]
  {\fontsize{36}{44}\selectfont\bfseries\color{accent}%
    Resilience Amid Uncertainty}\\[10pt]
  {\fontsize{26}{34}\selectfont\color{white!80}%
    World Bank Group~$\cdot$~Policy Brief~$\cdot$~2025}\\[6pt]
  \textcolor{white!55}{\rule{420pt}{0.8pt}}\\[6pt]
  {\fontsize{22}{28}\selectfont\color{white!70}%
    The global economy has staged its strongest recovery in six decades —\\
    yet resilience is uneven and downside risks are mounting.}
}

% ══════════════════════════════════════════════
% STAT BANNER (rows 4–7)
% ══════════════════════════════════════════════
\posterbox[
  enhanced,
  colback=primary!10!white,
  boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=8pt, bottom=8pt,
  valign=center,
  borderline south={2.5pt}{0pt}{primary!30},
]{name=stats, column=1, span=2, between=row4 and row7}{%
  \centering
  % Stat 1
  \begin{minipage}[c]{0.32\linewidth}\centering
    \fcolorbox{statborder}{stathighlight}{\parbox{0.90\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{52}{62}\selectfont\bfseries\color{primary} Strongest}\\[-2pt]
      {\fontsize{28}{34}\selectfont\bfseries\color{accent!90!black} in 6 Decades}\\[3pt]
      {\fontsize{20}{26}\selectfont\color{textgray} Recovery since 2020 recession}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  % Stat 2
  \begin{minipage}[c]{0.32\linewidth}\centering
    \fcolorbox{teal!60}{teal!10}{\parbox{0.90\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{52}{62}\selectfont\bfseries\color{primary} 1.2B}\\[-2pt]
      {\fontsize{22}{28}\selectfont\bfseries\color{teal} Youth entering workforce}\\[3pt]
      {\fontsize{20}{26}\selectfont\color{textgray} Over the next decade}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  % Stat 3
  \begin{minipage}[c]{0.32\linewidth}\centering
    \fcolorbox{secondary!50}{secondary!8}{\parbox{0.90\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{52}{62}\selectfont\bfseries\color{primary} 5}\\[-2pt]
      {\fontsize{22}{28}\selectfont\bfseries\color{secondary} Flagship 2030 Targets}\\[3pt]
      {\fontsize{20}{26}\selectfont\color{textgray} Health, energy, water, agri, capital}\vspace{5pt}%
    }}
  \end{minipage}
}

% ══════════════════════════════════════════════
% COLUMN 1 — LEFT
% ══════════════════════════════════════════════

% Section 1: Historic Recovery (rows 7–11)
\posterbox[navycard, title={A Historic Recovery — But Uneven}
]{name=recovery, column=1, between=row7 and row11}{%
  \fontsize{27}{36}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item Last year's growth capped the \textbf{strongest post-recession recovery in 60 years}
    \item Headline resilience masks a widening gap:\\
      advanced economies \& strong peers outpace\\
      \textbf{vulnerable EMDEs} significantly
    \item Current-year global growth edging \textbf{downward}:\\
      inventory drawdowns + tariff effects
    \item Financial market deterioration could\\
      further tighten EMDE financing conditions
  \end{itemize}
  \vspace{8pt}
  \colorbox{primary!18}{\parbox{0.94\linewidth}{%
    \centering\fontsize{25}{32}\selectfont\color{primary}%
    \textbf{Vulnerable EMDEs} continue to lag well\\
    behind advanced economies \& robust peers
  }}
}

% Section 2: Risks to the Outlook (rows 11–16)
\posterbox[ambercard, title={Risks to the Outlook}
]{name=risks, column=1, between=row11 and row16}{%
  \fontsize{27}{36}\selectfont
  \begin{enumerate}[itemsep=10pt, label={\color{accent!80!black}\bfseries\arabic*.}]
    \item \textbf{Trade Tensions} — Tariff escalation\\
      disrupts supply chains \& dampens investment
    \item \textbf{Financial Volatility} — Sentiment\\
      deterioration tightens EMDE financing
    \item \textbf{Inventory Correction} — Front-loaded\\
      purchases now drawing down, reducing demand
    \item \textbf{Climate Shocks} — Extreme weather\\
      threatens agriculture \& infrastructure
  \end{enumerate}
  \vspace{6pt}
  \colorbox{accent!20}{\parbox{0.94\linewidth}{%
    \centering\fontsize{25}{32}\selectfont\color{accent!80!black}%
    \textbf{Risk scenario:} Trade escalation or\\
    financial shock could derail recovery
  }}
}

% Section 3: Policy Actions (rows 16–20)
\posterbox[tealcard, title={Policy Actions for Sustained Growth}
]{name=policy, column=1, between=row16 and bottom}{%
  \fontsize{25}{33}\selectfont
  \renewcommand{\arraystretch}{1.55}
  \begin{tabular}{@{}p{0.26\linewidth}p{0.33\linewidth}p{0.33\linewidth}@{}}
    \rowcolor{teal!15}
    {\fontsize{22}{28}\selectfont\bfseries\color{teal} Area} &
    {\fontsize{22}{28}\selectfont\bfseries\color{teal} Global} &
    {\fontsize{22}{28}\selectfont\bfseries\color{teal} Domestic} \\
    \rowcolor{white}
    Trade & Multilateral env. & Diversify partners \\
    \rowcolor{teal!8}
    Finance & Ease EMDE financing & Macro frameworks \\
    \rowcolor{white}
    Climate & Scale mitigation & Resilient infra \\
    \rowcolor{teal!8}
    Investment & Private capital & Remove bottlenecks \\
    \rowcolor{white}
    Jobs & Labor mobility & Skills development \\
  \end{tabular}
}

% ══════════════════════════════════════════════
% COLUMN 2 — RIGHT
% ══════════════════════════════════════════════

% Section 4: WB 2030 Priorities (rows 7–13)
\posterbox[highlightcard, title={World Bank 2030 Strategic Priorities}
]{name=priorities, column=2, between=row7 and row13}{%
  \fontsize{26}{34}\selectfont
  \vspace{4pt}
  % Health
  \colorbox{secondary!15}{\parbox{0.94\linewidth}{%
    \fontsize{25}{32}\selectfont
    \textbf{\color{secondary}Health Services}~~{\color{primary}\Large$\to$}~~\textbf{1.5 billion people}\\
    Quality, affordable care delivered
  }}\vspace{5pt}

  % Electricity
  \colorbox{teal!15}{\parbox{0.94\linewidth}{%
    \fontsize{25}{32}\selectfont
    \textbf{\color{teal}Mission 300 (Electricity)}~~{\color{primary}\Large$\to$}~~\textbf{300M people}\\
    Sub-Saharan Africa electricity access
  }}\vspace{5pt}

  % AgriConnect
  \colorbox{primary!12}{\parbox{0.94\linewidth}{%
    \fontsize{25}{32}\selectfont
    \textbf{\color{primary}AgriConnect}~~{\color{primary}\Large$\to$}~~\textbf{300M farmers}\\
    Move up agricultural value chain
  }}\vspace{5pt}

  % Women's Capital
  \colorbox{accent!18}{\parbox{0.94\linewidth}{%
    \fontsize{25}{32}\selectfont
    \textbf{\color{accent!80!black}Women's Capital Access}~~{\color{primary}\Large$\to$}~~\textbf{80M women}\\
    Women \& women-led business capital
  }}\vspace{5pt}

  % Water
  \colorbox{secondary!10}{\parbox{0.94\linewidth}{%
    \fontsize{25}{32}\selectfont
    \textbf{\color{secondary}Water Forward}~~{\color{primary}\Large$\to$}~~\textbf{1B+ people}\\
    Water security; WBG \$400M commitment
  }}
}

% Section 5: Research Themes (rows 13–18)
\posterbox[bluecard, title={Key Research Themes}
]{name=research, column=2, between=row13 and row18}{%
  \fontsize{26}{34}\selectfont
  \renewcommand{\arraystretch}{1.5}
  \begin{tabular}{@{}p{0.30\linewidth}p{0.64\linewidth}@{}}
    \rowcolor{secondary!12}
    {\fontsize{22}{28}\selectfont\bfseries\color{secondary} Theme} &
    {\fontsize{22}{28}\selectfont\bfseries\color{secondary} Selected Topics} \\
    \rowcolor{white}
    Fiscal Policy & Rebuilding fiscal space; rules for small states \\
    \rowcolor{secondary!7}
    Trade \& Supply & High trade costs; GVC \& COVID impacts \\
    \rowcolor{white}
    Commodities & Price cycles; Russia-Ukraine energy shock \\
    \rowcolor{secondary!7}
    Financial & U.S. rate spillovers; debt buildup waves \\
    \rowcolor{white}
    Pandemic & Inequality impacts; regional macro effects \\
  \end{tabular}
  \vspace{8pt}
  \colorbox{secondary!15}{\parbox{0.94\linewidth}{%
    \centering\fontsize{24}{30}\selectfont\color{secondary}%
    Evidence-based analysis underpins all\\
    policy recommendations
  }}
}

% Footer / Source (rows 18–20)
\posterbox[
  enhanced, colback=primary!88!black, colframe=primary!88!black,
  arc=0pt, boxrule=0pt,
  left=20pt, right=20pt, top=8pt, bottom=8pt,
  valign=center,
]{name=footer, column=2, between=row18 and bottom}{%
  \fontsize{22}{30}\selectfont\color{white!85}
  \textbf{\color{accent}Source:} World Bank. \textit{Global Economic Prospects}, 2025.\\[4pt]
  \textbf{\color{accent}For more:} worldbank.org/gep\\[4pt]
  {\fontsize{20}{26}\selectfont\color{white!65}%
    This poster synthesizes key findings on global growth resilience,\\
    downside risks, and the World Bank's strategic 2030 priorities.}
}

\end{tcbposter}
\end{document}

