\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── World Bank Institutional Palette ──
\definecolor{primary}{HTML}{003366}
\definecolor{secondary}{HTML}{0058A3}
\definecolor{accent}{HTML}{C47A0A}
\definecolor{teal}{HTML}{007B7F}
\definecolor{bgposter}{HTML}{ECF0F6}
\definecolor{redbg}{HTML}{EDF3FB}
\definecolor{bluebg}{HTML}{E7F4F4}
\definecolor{darkbg}{HTML}{EAEFF0}
\definecolor{amberbg}{HTML}{FBF3DE}
\definecolor{redtitlebg}{HTML}{CFE1F2}
\definecolor{bluetitlebg}{HTML}{C6E5E5}
\definecolor{darktitlebg}{HTML}{CBDAE0}
\definecolor{ambertitlebg}{HTML}{F5E1AD}
\definecolor{textdark}{HTML}{0F1929}
\definecolor{textgray}{HTML}{374151}
\definecolor{stathighlight}{HTML}{FEF0C2}
\definecolor{statborder}{HTML}{9A5E06}
\definecolor{statbg2}{HTML}{E0EEF8}
\definecolor{statbg3}{HTML}{E0F0F0}

\pagecolor{bgposter}
\color{textdark}

\setlist[itemize]{leftmargin=18pt, itemsep=7pt, parsep=0pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=8pt, parsep=0pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

\tcbset{
  navycard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{primary},
    left=12pt, right=11pt, top=3pt, bottom=4pt,
    fonttitle=\fontsize{33}{41}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=redtitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={primary!38},
    valign=top, drop shadow={opacity=0.14},
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{teal},
    left=12pt, right=11pt, top=3pt, bottom=4pt,
    fonttitle=\fontsize{33}{41}\selectfont\bfseries\color{teal},
    coltitle=teal, colbacktitle=bluetitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={teal!38},
    valign=top, drop shadow={opacity=0.14},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{secondary},
    left=12pt, right=11pt, top=3pt, bottom=4pt,
    fonttitle=\fontsize{33}{41}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=darktitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={secondary!38},
    valign=top, drop shadow={opacity=0.14},
  },
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=amberbg,
    borderline west={5pt}{0pt}{accent},
    left=12pt, right=11pt, top=3pt, bottom=4pt,
    fonttitle=\fontsize{33}{41}\selectfont\bfseries\color{accent!85!black},
    coltitle=accent!85!black, colbacktitle=ambertitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={accent!45},
    valign=top, drop shadow={opacity=0.14},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!11!white,
    borderline west={6pt}{0pt}{primary},
    left=12pt, right=11pt, top=3pt, bottom=4pt,
    fonttitle=\fontsize{33}{41}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=5pt, bottomtitle=5pt,
    valign=top, drop shadow={opacity=0.17},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ── COMBINED TITLE + STAT HEADER (top → row5) ──
% 5 rows × 42mm = 210mm — fits both title and stats
\posterbox[
  enhanced, colback=primary, colframe=primary,
  arc=0pt, boxrule=0pt,
  left=0pt, right=0pt, top=0pt, bottom=0pt,
  halign=center, valign=top,
  drop shadow={opacity=0.22}
]{name=header, column=1, span=2, between=top and row5}{%
  % ── Title portion ──
  \begin{tcolorbox}[
    enhanced, colback=primary, colframe=primary,
    arc=0pt, boxrule=0pt,
    left=28pt, right=28pt, top=12pt, bottom=10pt,
    halign=center, valign=center,
  ]
  {\fontsize{60}{72}\selectfont\bfseries\color{white}%
    Global Economic Prospects}\\[5pt]
  {\fontsize{34}{42}\selectfont\bfseries\color{accent}%
    Resilience Amid Uncertainty}\\[8pt]
  {\fontsize{21}{27}\selectfont\color{white!75}%
    World Bank Group~$\cdot$~Policy Brief~$\cdot$~2025}\\[5pt]
  {\fontsize{19}{25}\selectfont\color{white!65}%
    The global economy staged its strongest recovery in six decades —
    yet resilience is uneven and downside risks are mounting.}
  \end{tcolorbox}
  % ── Stats strip ──
  \begin{tcolorbox}[
    enhanced, colback=primary!14!white, colframe=primary!14!white,
    arc=0pt, boxrule=0pt,
    left=10pt, right=10pt, top=9pt, bottom=9pt,
    halign=center, valign=center,
    borderline north={1.5pt}{0pt}{white!30},
  ]
  \centering
  \begin{minipage}[c]{0.32\linewidth}\centering
    \fcolorbox{statborder}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{46}{56}\selectfont\bfseries\color{primary} Strongest}\\[-2pt]
      {\fontsize{26}{32}\selectfont\bfseries\color{accent} in 6 Decades}\\[3pt]
      {\fontsize{19}{24}\selectfont\color{textgray} Post-2020 recovery}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.32\linewidth}\centering
    \fcolorbox{teal!50}{statbg3}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{46}{56}\selectfont\bfseries\color{primary} 1.2B}\\[-2pt]
      {\fontsize{20}{25}\selectfont\bfseries\color{teal} Youth entering workforce}\\[3pt]
      {\fontsize{19}{24}\selectfont\color{textgray} Over the next decade}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.32\linewidth}\centering
    \fcolorbox{secondary!42}{statbg2}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{46}{56}\selectfont\bfseries\color{primary} 5}\\[-2pt]
      {\fontsize{20}{25}\selectfont\bfseries\color{secondary} Flagship 2030 Targets}\\[3pt]
      {\fontsize{19}{24}\selectfont\color{textgray} Health, energy, water, agri, capital}\vspace{6pt}%
    }}
  \end{minipage}
  \end{tcolorbox}
}

% ════════════════════════════════
% COLUMN 1 — LEFT  (rows 5–20)
% Recovery:  5→10  (5 rows = 210mm)
% Risks:    10→15  (5 rows = 210mm)
% Policy:   15→20  (5 rows = 210mm)
% ════════════════════════════════

\posterbox[navycard, title={A Historic Recovery — But Uneven}
]{name=recovery, column=1, between=row5 and row10}{%
  \fontsize{27}{36}\selectfont
  \begin{itemize}[itemsep=9pt]
    \item Last year's growth capped the \textbf{strongest post-recession recovery in 60 years}
    \item Headline resilience masks a \textbf{widening gap}: advanced economies outpace \textbf{vulnerable EMDEs} significantly
    \item Current-year global growth edging \textbf{downward}: inventory drawdowns + tariff effects
    \item Financial market deterioration could further tighten EMDE financing conditions
  \end{itemize}
  \vspace{8pt}
  \colorbox{primary!18}{\parbox{0.94\linewidth}{%
    \centering\fontsize{25}{32}\selectfont\color{primary}%
    \textbf{Vulnerable EMDEs} continue to lag well behind\\
    advanced economies \& more robust peers
  }}
}

\posterbox[ambercard, title={Risks to the Outlook}
]{name=risks, column=1, between=row10 and row15}{%
  \fontsize{27}{36}\selectfont
  \begin{enumerate}[itemsep=10pt, label={\color{accent!88!black}\bfseries\arabic*.}]
    \item \textbf{Trade Tensions} — Tariff escalation disrupts supply chains \& dampens investment
    \item \textbf{Financial Volatility} — Sentiment deterioration tightens EMDE financing
    \item \textbf{Inventory Correction} — Front-loaded purchases now drawing down, reducing demand
    \item \textbf{Climate Shocks} — Extreme weather threatens agriculture \& infrastructure
  \end{enumerate}
  \vspace{8pt}
  \colorbox{accent!22}{\parbox{0.94\linewidth}{%
    \centering\fontsize{25}{32}\selectfont\color{accent!85!black}%
    \textbf{Key risk:} Trade escalation or financial shock\\
    could derail the global recovery
  }}
}

\posterbox[tealcard, title={Policy Actions for Sustained Growth}
]{name=policy, column=1, between=row15 and bottom}{%
  \fontsize{25}{33}\selectfont
  \renewcommand{\arraystretch}{1.68}
  \setlength{\tabcolsep}{6pt}
  \begin{tabular}{@{}p{0.21\linewidth}p{0.38\linewidth}p{0.35\linewidth}@{}}
    \rowcolor{teal!17}
    {\fontsize{22}{28}\selectfont\bfseries\color{teal} Area} &
    {\fontsize{22}{28}\selectfont\bfseries\color{teal} Global Action} &
    {\fontsize{22}{28}\selectfont\bfseries\color{teal} Domestic Action} \\
    \rowcolor{white}
    Trade & Multilateral trade env. & Diversify partners \\
    \rowcolor{teal!8}
    Finance & Ease EMDE financing & Macro frameworks \\
    \rowcolor{white}
    Climate & Scale mitigation & Resilient infra \\
    \rowcolor{teal!8}
    Investment & Catalyze private capital & Remove bottlenecks \\
    \rowcolor{white}
    Jobs & Cross-border mobility & Skills development \\
  \end{tabular}
}

% ════════════════════════════════
% COLUMN 2 — RIGHT  (rows 5–20)
% Priorities: 5→12  (7 rows = 294mm)
% Research:  12→17  (5 rows = 210mm)
% Footer:    17→20  (3 rows = 126mm)
% ════════════════════════════════

\posterbox[highlightcard, title={World Bank 2030 Strategic Priorities}
]{name=priorities, column=2, between=row5 and row12}{%
  \fontsize{25}{33}\selectfont
  \vspace{4pt}
  \colorbox{secondary!15}{\parbox{0.94\linewidth}{%
    \fontsize{24}{31}\selectfont
    \textbf{\color{secondary}Health Services}\hfill\textbf{\color{primary}1.5 billion people}\\[1pt]
    {\fontsize{20}{26}\selectfont\color{textgray}Quality, affordable care delivered globally}
  }}\vspace{6pt}

  \colorbox{teal!13}{\parbox{0.94\linewidth}{%
    \fontsize{24}{31}\selectfont
    \textbf{\color{teal}Mission 300 — Electricity}\hfill\textbf{\color{primary}300M people}\\[1pt]
    {\fontsize{20}{26}\selectfont\color{textgray}Sub-Saharan Africa electricity access}
  }}\vspace{6pt}

  \colorbox{primary!12}{\parbox{0.94\linewidth}{%
    \fontsize{24}{31}\selectfont
    \textbf{\color{primary}AgriConnect}\hfill\textbf{\color{primary}300M farmers}\\[1pt]
    {\fontsize{20}{26}\selectfont\color{textgray}Move up the agricultural value chain}
  }}\vspace{6pt}

  \colorbox{accent!18}{\parbox{0.94\linewidth}{%
    \fontsize{24}{31}\selectfont
    \textbf{\color{accent!85!black}Women's Capital Access}\hfill\textbf{\color{primary}80M women}\\[1pt]
    {\fontsize{20}{26}\selectfont\color{textgray}Women \& women-led business capital}
  }}\vspace{6pt}

  \colorbox{secondary!9}{\parbox{0.94\linewidth}{%
    \fontsize{24}{31}\selectfont
    \textbf{\color{secondary}Water Forward}\hfill\textbf{\color{primary}1B+ people}\\[1pt]
    {\fontsize{20}{26}\selectfont\color{textgray}Water security; WBG \$400M commitment}
  }}
}

\posterbox[bluecard, title={Key Research Themes in Recent Issues}
]{name=research, column=2, between=row12 and row17}{%
  \fontsize{25}{33}\selectfont
  \renewcommand{\arraystretch}{1.58}
  \setlength{\tabcolsep}{7pt}
  \begin{tabular}{@{}p{0.30\linewidth}p{0.64\linewidth}@{}}
    \rowcolor{secondary!13}
    {\fontsize{21}{27}\selectfont\bfseries\color{secondary} Theme} &
    {\fontsize{21}{27}\selectfont\bfseries\color{secondary} Selected Topics} \\
    \rowcolor{white}
    Fiscal Policy & Rebuilding fiscal space; fiscal rules for small states \\
    \rowcolor{secondary!7}
    Trade \& Supply Chains & High trade costs; GVC \& COVID-19 impacts \\
    \rowcolor{white}
    Commodity Markets & Price cycles; Russia-Ukraine energy implications \\
    \rowcolor{secondary!7}
    Financial Spillovers & Rising U.S. interest rates; fourth debt buildup wave \\
    \rowcolor{white}
    Pandemic Economics & Global income inequality; regional macro effects \\
  \end{tabular}
  \vspace{7pt}
  \colorbox{secondary!14}{\parbox{0.94\linewidth}{%
    \centering\fontsize{22}{28}\selectfont\color{secondary}%
    Evidence-based analysis underpins all Bank policy recommendations
  }}
}

\posterbox[
  enhanced, colback=primary!88!black, colframe=primary!88!black,
  arc=0pt, boxrule=0pt,
  left=18pt, right=18pt, top=10pt, bottom=10pt,
  valign=center,
]{name=footer, column=2, between=row17 and bottom}{%
  \fontsize{22}{30}\selectfont\color{white!85}
  \textbf{\color{accent}Source:}\enspace
  World Bank. \textit{Global Economic Prospects}, 2025.
  \enspace\textbf{\color{accent}worldbank.org/gep}\\[6pt]
  {\fontsize{19}{26}\selectfont\color{white!62}%
    This poster distills findings on global growth resilience, downside risks,\\
    policy priorities, and the World Bank's strategic 2030 targets.}
}

\end{tcbposter}
\end{document}

