% ════════════════════════════════

\posterbox[navycard, title={A Historic Recovery — But Uneven}
]{name=recovery, column=1, between=row5 and row10}{%
  \fontsize{27}{36}\selectfont
  \begin{itemize}[itemsep=9pt]
    \item Last year's growth capped the \textbf{strongest post-recession recovery in 60 years}
    \item Headline resilience masks a \textbf{widening gap}: advanced economies outpace \textbf{vulnerable EMDEs} significantly
    \item Current-year global growth edging \textbf{downward}: inventory drawdowns + tariff effects
    \item Financial market deterioration could further tighten EMDE financing conditions
  \end{itemize}
  \vspace{8pt}
  \colorbox{primary!18}{\parbox{0.94\linewidth}{%
    \centering\fontsize{25}{32}\selectfont\color{primary}%
    \textbf{Vulnerable EMDEs} continue to lag well behind\\
    advanced economies \& more robust peers
  }}
}

\posterbox[ambercard, title={Risks to the Outlook}
]{name=risks, column=1, between=row10 and row15}{%
  \fontsize{27}{36}\selectfont
  \begin{enumerate}[itemsep=10pt, label={\color{accent!88!black}\bfseries\arabic*.}]
    \item \textbf{Trade Tensions} — Tariff escalation disrupts supply chains \& dampens investment
    \item \textbf{Financial Volatility} — Sentiment deterioration tightens EMDE financing
    \item \textbf{Inventory Correction} — Front-loaded purchases now drawing down, reducing demand
    \item \textbf{Climate Shocks} — Extreme weather threatens agriculture \& infrastructure
  \end{enumerate}
  \vspace{8pt}
  \colorbox{accent!22}{\parbox{0.94\linewidth}{%
    \centering\fontsize{25}{32}\selectfont\color{accent!85!black}%
    \textbf{Key risk:} Trade escalation or financial shock\\
    could derail the global recovery
  }}
}

\posterbox[tealcard, title={Policy Actions for Sustained Growth}
]{name=policy, column=1, between=row15 and bottom}{%
  \fontsize{25}{33}\selectfont
  \renewcommand{\arraystretch}{1.70}
