    {\fontsize{22}{28}\selectfont\bfseries\color{teal} Global Action} &
    {\fontsize{22}{28}\selectfont\bfseries\color{teal} Domestic Action} \\
    \rowcolor{white}
    Trade & Multilateral trade env. & Diversify partners \\
    \rowcolor{teal!8}
    Finance & Ease EMDE financing & Macro frameworks \\
    \rowcolor{white}
    Climate & Scale mitigation & Resilient infra \\
    \rowcolor{teal!8}
    Investment & Catalyze private capital & Remove bottlenecks \\
    \rowcolor{white}
    Jobs & Cross-border mobility & Skills development \\
  \end{tabular}
}

