% ── UNIFIED HEADER BACKGROUND (top → row8) ──
% One seamless navy box covering the entire header zone
\posterbox[
  enhanced, colback=primary, colframe=primary,
  arc=0pt, boxrule=0pt,
  left=0pt, right=0pt, top=0pt, bottom=0pt,
]{name=headerbg, column=1, span=2, between=top and row8}{}

