      {\fontsize{19}{24}\selectfont\bfseries\color{teal!70!white} Youth entering workforce}\\[3pt]
      {\fontsize{17}{22}\selectfont\color{white!55} Over the next decade}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.32\linewidth}\centering
    \fcolorbox{secondary!60!primary}{statbg2}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
