      {\fontsize{19}{24}\selectfont\bfseries\color{secondary!60!white} Flagship 2030 Targets}\\[3pt]
      {\fontsize{17}{22}\selectfont\color{white!55} Health, energy, water, agri, capital}\vspace{6pt}%
    }}
  \end{minipage}
}

% ── ACCENT DIVIDER BAR (row7 → row8) ──
\posterbox[
  enhanced, colback=accent!85!black, colframe=accent!85!black,
