  left=20pt, right=20pt, top=6pt, bottom=6pt,
  halign=center, valign=center,
]{name=divbar, column=1, span=2, between=row7 and row8}{%
  {\fontsize{17}{22}\selectfont\color{white!80}%
    \textbf{Recovery~$\cdot$~Resilience~$\cdot$~Reform}%
    \quad\textcolor{white!45}{$|$}\quad%
    World Bank policy agenda for sustainable and inclusive growth}
}

