% Priorities:  8→16  (8 rows = 224mm)
% Research:   16→23  (7 rows = 196mm)
% Footer:     23→30  (7 rows = 196mm)
% ════════════════════════════════

\posterbox[highlightcard, title={World Bank 2030 Strategic Priorities}
]{name=priorities, column=2, between=row8 and row16}{%
  \fontsize{25}{33}\selectfont
